+#!/usr/bin/env node
+// Validates SQL queries against schema at build time
+// Run before deploying to catch schema mismatches early
+
+import fs from "fs";
+import path from "path";
+import { fileURLToPath } from "url";
+
+const __dir = path.dirname(fileURLToPath(import.meta.url));
+const repoRoot = path.resolve(__dir, "..");
+const schemaPath = path.join(repoRoot, "src/db/schema.sql");
+const typesPath = path.join(repoRoot, "src/db/schema-types.ts");
+
+const schema = fs.readFileSync(schemaPath, "utf-8");
+const types = fs.readFileSync(typesPath, "utf-8");
+
+// Extract table definitions from schema
+const tableRegex = /CREATE TABLE (\w+)\s*\(([\s\S]*?)\);/g;
+const tables = {};
+let match;
+
+while ((match = tableRegex.exec(schema)) !== null) {
+  const [, tableName, columnsStr] = match;
+  const columns = new Map();
+
+  const columnLines = columnsStr
+    .split(",")
+    .map((line) => line.trim())
+    .filter((line) => line && !line.startsWith("CONSTRAINT"));
+
+  columnLines.forEach((line) => {
+    const [name] = line.split(/\s+/);
+    if (name && name !== "PRIMARY" && name !== "FOREIGN") {
+      columns.set(name, true);
+    }
+  });
+
+  tables[tableName] = columns;
+}
+
+// Extract interfaces from types
+const interfaceRegex = /export interface (\w+)\s*\{([\s\S]*?)\}/g;
+const typeInterfaces = {};
+
+while ((match = interfaceRegex.exec(types)) !== null) {
+  const [, interfaceName, propsStr] = match;
+  const props = new Set();
+
+  propsStr
+    .split(";")
+    .map((line) => line.trim())
+    .filter((line) => line)
+    .forEach((prop) => {
+      const [name] = prop.split(":");
+      if (name) props.add(name);
+    });
+
+  typeInterfaces[interfaceName] = props;
+}
+
+// Validate: TypeScript interfaces match database schema
+let errors = [];
+
+for (const [tableName, typeInterface] of Object.entries(typeInterfaces)) {
+  if (tableName === "DbRow") continue; // Union type, skip
+
+  const tableNameLower = tableName.toLowerCase();
+  const schemaColumns = tables[tableNameLower];
+
+  if (!schemaColumns) {
+    errors.push(`Type "${tableName}" has no matching table "${tableNameLower}" in schema.sql`);
+    continue;
+  }
+
+  // Check that interface fields match schema columns
+  for (const typeField of typeInterface) {
+    if (!schemaColumns.has(typeField)) {
+      errors.push(
+        `Type "${tableName}" has field "${typeField}" not in schema "${tableNameLower}" table`
+      );
+    }
+  }
+
+  // Warn if schema has columns not in type
+  for (const schemaCol of schemaColumns.keys()) {
+    if (!typeInterface.has(schemaCol)) {
+      console.warn(
+        `⚠ Schema "${tableNameLower}" has column "${schemaCol}" not in type "${tableName}"`
+      );
+    }
+  }
+}
+
+if (errors.length > 0) {
+  console.error("❌ Schema validation failed:\n");
+  errors.forEach((e) => console.error(`  ${e}`));
+  process.exit(1);
+} else {
+  console.log("✓ Schema types match database schema");
+}
