+// Regenerate with: npm run db:gen
+
+export interface User {
+  id: string;
+  email: string;
+  created_at: Date;
+}
+
+export interface AuditLog {
+  id: number;
+  actor: string;
+  action: string;
+  created_at: Date;
+}
+
+export type DbRow = User | AuditLog;
